import { useState } from "react";
import "./Chip.css";

/**
 * Tidepool chip (Figma node 3:16) — "A filter people switch on and off."
 * Icon only renders for Size="L" (Figma defines no Size=M, Icon=True variant).
 */
export function Chip({
  Size = "M",
  Icon = false,
  Label = "Filter",
  pressed,
  defaultPressed = false,
  onPressedChange,
  className,
  onClick,
  ...rest
}) {
  const [internalPressed, setInternalPressed] = useState(defaultPressed);
  const isPressed = pressed !== undefined ? pressed : internalPressed;
  const showIcon = Icon && Size === "L";

  const handleClick = (event) => {
    onClick?.(event);
    const next = !isPressed;
    if (pressed === undefined) setInternalPressed(next);
    onPressedChange?.(next);
  };

  const classes = ["chip", Size === "L" && "chip--l", className].filter(Boolean).join(" ");

  return (
    <button
      type="button"
      aria-pressed={isPressed}
      className={classes}
      onClick={handleClick}
      {...rest}
    >
      {showIcon && <span className="chip__icon" aria-hidden="true" />}
      <span className="chip__label">{Label}</span>
    </button>
  );
}

export default Chip;

