import "./Field.css";

export function Field({ label, id, state = "Default", disabled, className = "", ...inputProps }) {
  const isError = state === "Error";
  const inputId = id || (label ? label.toLowerCase().replace(/\s+/g, "-") : undefined);

  const fieldClassName = ["field", isError ? "field--error" : "", className].filter(Boolean).join(" ");

  const input = (
    <input
      id={inputId}
      type="text"
      disabled={disabled}
      aria-invalid={isError || undefined}
      className={fieldClassName}
      {...inputProps}
    />
  );

  if (!label) return input;

  return (
    <div className="field-group">
      <label className="field-label" htmlFor={inputId}>
        {label}
      </label>
      {input}
    </div>
  );
}

export default Field;

